import itertools

def brute_force(password, attempts):
    for guess in itertools.product('abcdefghijklmnopqrstuvwxyz', repeat=3):
        guess = ''.join(guess)
        attempts[guess] = True
        if guess == password:
            return guess
    return None

def main():
    password = input("Enter the password: ")
    attempts = {}
    found_password = brute_force(password, attempts)

    if found_password:
        print(f"Password found: {found_password}")
    else:
